        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = pow2[i - 1] * 2 % MOD;
        }

        // Precompute inverse of 2
        long inv2 = modInverse(2, MOD);

        // Precompute powers of inv2 up to n
        long[] invPow2 = new long[n + 1];
        invPow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            invPow2[i] = invPow2[i - 1] * inv2 % MOD;
        }

